const prs = $input.first().json;
if (!Array.isArray(prs) || prs.length === 0) {
  return [{ json: { skip: true, reason: 'No open PRs' } }];
}

const now = new Date();
const oneHourAgo = new Date(now - 3600000);
const oneDayAgo = new Date(now - 86400000);
const threeDaysAgo = new Date(now - 3 * 86400000);

const enriched = prs.map(pr => {
  const updatedAt = new Date(pr.updated_at);
  const createdAt = new Date(pr.created_at);
  const ageHours = Math.floor((now - createdAt) / 3600000);
  const ageDays = Math.floor(ageHours / 24);
  const isStale = createdAt < threeDaysAgo && updatedAt < threeDaysAgo;
  const isRecentlyUpdated = updatedAt >= oneHourAgo;
  const isDraft = pr.draft || false;
  const reviewers = (pr.requested_reviewers || []).map(r => r.login);
  const labels = (pr.labels || []).map(l => l.name);

  return {
    number: pr.number,
    title: pr.title,
    author: pr.user?.login || 'unknown',
    url: pr.html_url,
    isDraft,
    isStale,
    isRecentlyUpdated,
    ageHours,
    ageDays,
    reviewers,
    labels,
    reviewCount: pr.requested_reviewers?.length || 0,
    additions: pr.additions || 0,
    deletions: pr.deletions || 0,
    changedFiles: pr.changed_files || 0,
    body: (pr.body || '').slice(0, 500),
    createdAt: pr.created_at,
    updatedAt: pr.updated_at,
    baseBranch: pr.base?.ref || 'main',
    headBranch: pr.head?.ref || ''
  };
});

const stalePRs = enriched.filter(p => p.isStale && !p.isDraft);
const urgentPRs = enriched.filter(p => !p.isDraft && p.reviewCount === 0 && p.ageHours > 4);
const recentlyUpdated = enriched.filter(p => p.isRecentlyUpdated && !p.isDraft);
const allOpen = enriched.filter(p => !p.isDraft);
const drafts = enriched.filter(p => p.isDraft);

return [{
  json: {
    skip: false,
    allOpen,
    stalePRs,
    urgentPRs,
    recentlyUpdated,
    drafts,
    repo: `${$env.GITHUB_OWNER}/${$env.GITHUB_REPO}`,
    generatedAt: now.toISOString()
  }
}];

